 public sealed class LatencyProfileFormA01:Form {
  readonly Func<LatencySettingsA01> settings;readonly DataGridView grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect};
  readonly FlowLayoutPanel actions=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};readonly Label status=new Label{Dock=DockStyle.Fill};readonly NumericUpDown tolerance=Number(5,0,1000,2),margin=Number(0,0,100,2),repetitions=Number(10,1,100,0),channel=Number(1,1,16,0),note=Number(60,0,127,0),search=Number(250,10,1000,0),ukTrack=Number(0,0,16,0);readonly TextBox conditions=new TextBox{Width=400};readonly CheckBox video=new CheckBox{Text="Sans mesure vidéo : utiliser l’audio comme hypothèse",AutoSize=true};
  CancellationTokenSource cancellation;bool running;readonly Action<bool> adopt;FlowLayoutPanel optionsPanel;
  static NumericUpDown Number(decimal v,decimal min,decimal max,int decimals){return new Synkoz.ScrollNumberR8{Minimum=min,Maximum=max,Value=v,DecimalPlaces=decimals,Width=65};}
  public LatencyProfileFormA01(Func<LatencySettingsA01> get,Func<int,CancellationToken,Task<Montage>> capture,Func<bool,Task> load,Action save,Action<bool> apply){settings=get;adopt=apply;Text="Profil de latence des appareils";StartPosition=FormStartPosition.CenterParent;ClientSize=new Size(1080,660);MinimumSize=new Size(850,560);
   var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6,Padding=new Padding(8)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,125));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,80));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,70));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,32));Controls.Add(layout);
   layout.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Audio facultatif : microphones près de l’enceinte, son percussif. Vidéo : caméra fixe, filmer un Néo complet (Teensy) ou un appareil au visuel fort lors du déclenchement du son (MIDI). Éviter les autres lumières clignotantes.\nAnalyse locale sans IA, audio et vidéo séparés. Vidéo expérimentale aux horodatages natifs : 30 fps ≈ 33,33 ms de résolution, pas une précision de 5 ms. Minimum vidéo recommandé = borne avant la première image allumée.\nSérie : une mesure de 4 temps, préparation sans décompte lumineux ; prise normale : 4-3-2-1 conservé. Une absence de repère est signalée sans supprimer les autres mesures."},0,0);
   var options=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};optionsPanel=options;Action<string,Control> field=(name,c)=>{options.Controls.Add(new Label{Text=name,AutoSize=true,Margin=new Padding(5,6,3,0)});options.Controls.Add(c);};field("Tolérance ms",tolerance);field("Minimum − marge ms",margin);field("Prises",repetitions);field("Canal MIDI",channel);field("Note",note);field("Recherche + ms",search);options.SetFlowBreak(search,true);field("Piste UK (0 = active)",ukTrack);field("Conditions / branchements",conditions);options.Controls.Add(video);layout.Controls.Add(options,0,1);
   Add("Enregistrer la série",async()=>{Read();for(int i=0;i<settings().Repetitions;i++){cancellation.Token.ThrowIfCancellationRequested();Report("Prise "+(i+1)+" / "+settings().Repetitions+" — préparation…");var m=await capture(i+1,cancellation.Token);Fill();await Analyze(m);}});
   Add("Analyser des prises…",async()=>{Read();using(var dialog=new OpenFileDialog{AutoUpgradeEnabled=true,Filter="Prises originales Snkoz|Montage.synkoz.json",Multiselect=true,Title="Choisir les prises à ajouter au profil"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;foreach(string path in dialog.FileNames){var m=Montage.Load(Path.GetDirectoryName(path));await Analyze(m);}}});
   Add("Charger config",async()=>{await load(false);Fill();});Add("Ajouter config",async()=>{await load(true);Fill();});Add("Sauver config",()=>{Read();save();Report("Enregistrer les réglages et résultats dans le fichier de configuration choisi.");return Task.FromResult(0);});Add("Adopter le profil recommandé",()=>{Read();adopt(video.Checked);Report("Profil adopté pour les prochaines prises. Utiliser Sauver config pour le conserver.");return Task.FromResult(0);});layout.Controls.Add(actions,0,2);
   foreach(string name in new[]{"Appareil / configuration","Prises","Mesures","Min ms","Max ms","Médiane ms","Variation ms","Correction ms","État"})grid.Columns.Add(name,name);grid.Columns[0].FillWeight=220;grid.Columns[8].FillWeight=180;layout.Controls.Add(grid,0,3);
   var details=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};grid.SelectionChanged+=delegate{if(grid.SelectedRows.Count==0)return;var d=grid.SelectedRows[0].Tag as LatencyDeviceA01;if(d!=null)details.Text=string.Join(Environment.NewLine,d.Samples.GroupBy(s=>s.Take).Select(g=>g.First().Date+" | "+g.Key+" | "+g.First().Conditions+" | min/max "+g.Min(s=>s.DelayMs).ToString("F2")+" / "+g.Max(s=>s.DelayMs).ToString("F2")+" ms").Concat(d.Diagnostics));};layout.Controls.Add(details,0,4);
   var footer=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};footer.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));footer.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,130));footer.Controls.Add(status,0,0);var stop=new Button{Text="Arrêter / Fermer",Dock=DockStyle.Fill};stop.Click+=delegate{if(running){cancellation.Cancel();Report("Arrêt demandé…");}else Close();};footer.Controls.Add(stop,1,0);layout.Controls.Add(footer,0,5);
   FormClosing+=delegate(object s,FormClosingEventArgs e){if(running){cancellation.Cancel();e.Cancel=true;Report("Arrêt demandé — attendre la fin de récupération des fichiers.");}else Read();};tolerance.ValueChanged+=delegate{Read();RefreshResults();};margin.ValueChanged+=delegate{Read();RefreshResults();};Fill();
  }
  void Add(string text,Func<Task> action){var b=new Button{Text=text,AutoSize=true};b.Click+=async delegate{if(running)return;running=true;actions.Enabled=false;optionsPanel.Enabled=false;Read();cancellation=new CancellationTokenSource();try{await action();}catch(OperationCanceledException){Report("Opération arrêtée ; résultats déjà obtenus conservés.");}catch(Exception ex){Report(ex.Message);}finally{running=false;actions.Enabled=true;optionsPanel.Enabled=true;cancellation.Dispose();cancellation=null;RefreshResults();}};actions.Controls.Add(b);}
  void Report(string text){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Report),text);return;}status.Text=text;}
  async Task Analyze(Montage m){var options=UiR2.Copy(settings());var result=await Task.Run(()=>LatencyAnalysisA01.Analyze(m,options,cancellation.Token,Report),cancellation.Token);settings().Merge(result);RefreshResults();Report("Analyse ajoutée : "+Path.GetFileName(m.Folder)+". Les prises déjà analysées ne sont pas comptées deux fois.");}
  bool filling;
  void Read(){if(filling)return;var s=settings();s.ToleranceMs=(double)tolerance.Value;s.MarginMs=(double)margin.Value;s.Repetitions=(int)repetitions.Value;s.UkTrack=(int)ukTrack.Value;s.Channel=(int)channel.Value;s.Note=(int)note.Value;s.SearchMs=(double)search.Value;s.Conditions=conditions.Text;}
  void Fill(){filling=true;try{var s=settings();s.Normalize();tolerance.Value=(decimal)s.ToleranceMs;margin.Value=(decimal)s.MarginMs;repetitions.Value=s.Repetitions;ukTrack.Value=s.UkTrack;channel.Value=s.Channel;note.Value=s.Note;search.Value=(decimal)s.SearchMs;conditions.Text=s.Conditions;}finally{filling=false;}RefreshResults();}
  void RefreshResults(){grid.Rows.Clear();foreach(var d in settings().Devices){bool measured=d.Samples.Count>0;double range=measured?d.Maximum-d.Minimum:0;string state=!measured?"Aucun repère exploitable":d.Takes<2?"Plusieurs prises nécessaires":range>settings().ToleranceMs?"Variable — à vérifier":"Stable sur ces mesures";if(d.Stream=="video"&&measured&&range<=settings().ToleranceMs&&d.Resolution>settings().ToleranceMs)state="Tolérance inférieure à la résolution vidéo";if(d.Stream=="video"&&measured)state+=" · résolution ≤ "+d.Resolution.ToString("F2")+" ms (expérimental)";if(d.Diagnostics.Count>0)state+=" · rejets : voir détails";int row=grid.Rows.Add(d.Name+" · "+d.Stream,d.Takes,d.Samples.Count,measured?d.Minimum.ToString("F2"):"—",measured?d.Maximum.ToString("F2"):"—",measured?d.Median.ToString("F2"):"—",measured?range.ToString("F2"):"—",measured?(-(d.RecommendedMinimum-settings().MarginMs)).ToString("F2"):"—",state);grid.Rows[row].Tag=d;if(!measured||range>settings().ToleranceMs||d.Stream=="video")grid.Rows[row].DefaultCellStyle.BackColor=Color.Moccasin;}}
 }
 public sealed partial class CapturePanel {
  LatencySettingsA01 latencyA01=new LatencySettingsA01();bool latencyTakingA01;
  void InitLatencyA01(){Button("Ajouter config",async()=>await LoadConfig(true));Button("Profil de latence",()=>{if(Busy||paused||DirectOpen939)return;using(var f=new LatencyProfileFormA01(()=>latencyA01,CaptureLatencyA01,append=>LoadConfig(append),SaveConfig,AdoptLatencyA01))f.ShowDialog(FindForm());});Button("Latences de prise",()=>{if(Busy||paused||DirectOpen939)return;using(var f=new CaptureDelaysA01(tracks))f.ShowDialog(FindForm());});}
  void AdoptLatencyA01(bool video){int count=0;foreach(var t in tracks){string key=LatencyAnalysisA01.Key(t);var profiles=latencyA01.Devices.Where(x=>x.Key==key&&x.Samples.Count>=4&&x.Takes>=2).ToArray();var audio=profiles.FirstOrDefault(d=>d.Stream=="audio");var optical=profiles.FirstOrDefault(d=>d.Stream=="video");if(audio==null&&optical==null)continue;
   if(audio!=null&&Engine.HasAudio(t))CalibrationTimeR5.Set(t.Fx,false,-(audio.RecommendedMinimum-latencyA01.MarginMs)/1000);
   bool proxy=optical==null&&audio!=null&&video&&t.Video!=null;
   if(t.Video!=null&&(optical!=null||proxy)){var source=optical??audio;CalibrationTimeR5.Set(t.Fx,true,-(source.RecommendedMinimum-latencyA01.MarginMs)/1000);}
   t.LatencyA01=new LatencyStampA01{Key=key,MinimumMs=profiles.Min(d=>d.Minimum),MaximumMs=profiles.Max(d=>d.Maximum),ToleranceMs=latencyA01.ToleranceMs,MarginMs=latencyA01.MarginMs,Takes=profiles.Min(d=>d.Takes),NeedsReview=optical!=null||profiles.Any(d=>d.Maximum-d.Minimum>latencyA01.ToleranceMs),VideoProxy=proxy};count++;
  }if(count==0)throw new Exception("Aucun profil correspondant avec au moins deux prises et quatre mesures. Charger/ajouter la configuration des appareils concernés.");}
  string seriesFolderA01,nextCalibrationFolderA01;
  async Task<Montage> CaptureLatencyA01(int ordinal,CancellationToken token){
   if(Busy||paused||DirectOpen939)throw new Exception("Terminer la prise ou le mode Direct avant le profil.");if(!tracks.Any(t=>Engine.HasAudio(t)||t.Video!=null))throw new Exception("Activer au moins un microphone ou une caméra pour le profil.");if(Universal941&&midiMode941.SelectedIndex!=1)throw new Exception("La série automatique demande MIDI maître PC ou Teensy avec Snkoz actif.");if(!Universal941)await ConfigureTestRouteA01(token);
   if(ordinal==1)seriesFolderA01=Engine.NewTake(Path.Combine(takeFolder936,"Calibration"),DateTime.Now);nextCalibrationFolderA01=Path.Combine(seriesFolderA01,"prise"+ordinal.ToString("D2"));Directory.CreateDirectory(nextCalibrationFolderA01);bool oldTest=test935.Checked,oldStart=startTee.Checked;latencyTakingA01=true;Exception failure=null;Montage result=null;
   try{if(!Universal941){test935.Checked=true;startTee.Checked=true;}await Start(false);if(!recording)throw new Exception(status.Text);var began=System.Diagnostics.Stopwatch.StartNew();while(true){token.ThrowIfCancellationRequested();if(shutting)throw new OperationCanceledException();if(!recording)throw new Exception("Enregistrement interrompu.");if(began.Elapsed.TotalSeconds>45)throw new Exception("Pas de mesure MIDI complète reçue en 45 secondes.");if(Universal941){DrainMidi941();if(marks.Count>1&&midiTicks941>=1536)break;}else if(!double.IsNaN(music)&&marks.Any(m=>m.Tick>=musicTick+1536))break;await Task.Delay(10,token);}await Task.Delay(150,token);await Finish(false);token.ThrowIfCancellationRequested();if(project==null||project.Duration<=0)throw new Exception("Prise vide ou non finalisée.");result=project;}
   catch(Exception ex){failure=ex;}if(recording)await Finish(false);latencyTakingA01=false;test935.Checked=oldTest;startTee.Checked=oldStart;if(failure!=null)throw failure;return result;
  }
 }
 public sealed class CaptureDelaysA01:Form {
  public CaptureDelaysA01(System.Collections.Generic.List<Track> tracks){Text="Latences des prochaines prises";ClientSize=new Size(760,450);StartPosition=FormStartPosition.CenterParent;var list=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};Controls.Add(list);var values=new System.Collections.Generic.List<Tuple<Track,NumericUpDown,NumericUpDown>>();list.Controls.Add(new Label{Text="Millisecondes : − avancer, + retarder. Conserver avec Sauver config.",AutoSize=true});foreach(var t in tracks.Where(t=>!t.Midi945)){var row=new FlowLayoutPanel{Width=710,Height=55};row.Controls.Add(new Label{Text=Sources936.Label(t),Width=210});var a=UiR2.Number(t.Fx.AudioShift*1000,-3600000,3600000,3);var v=UiR2.Number(t.Fx.Shift*1000,-3600000,3600000,3);a.Enabled=Engine.HasAudio(t);v.Enabled=t.Video!=null;row.Controls.Add(new Label{Text="Audio",AutoSize=true});row.Controls.Add(a);row.Controls.Add(new Label{Text="Vidéo",AutoSize=true});row.Controls.Add(v);list.Controls.Add(row);values.Add(Tuple.Create(t,a,v));}var ok=new Button{Text="Valider",AutoSize=true};ok.Click+=delegate{foreach(var x in values){if(x.Item2.Enabled)CalibrationTimeR5.Set(x.Item1.Fx,false,(double)x.Item2.Value/1000);if(x.Item3.Enabled)CalibrationTimeR5.Set(x.Item1.Fx,true,(double)x.Item3.Value/1000);}DialogResult=DialogResult.OK;Close();};list.Controls.Add(ok);}
 }
